insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'life_expectancy', 'census_actuarial_le_male', '1881', 1881, 23.67, 'census-actuarial-reports-1881-1951', '1931 Actuarial Report (in reprint volume), Table XXXI ''Comparative Expectations of Life at decennial ages, as deduced from the results of the 1881, 1891, 1901, 1911 and 1931 Censuses'', All India, age 0 (MALE LIVES)', 'PDF p.384 (males) & p.386 (females); printed pp.358, 360', '2026-10-16', null, false, 'MALES only (table prints no persons figure). Life table derived at this census for British Indian provinces. Hardy 1881 tables: ''India (combined provinces)'' = Madras, Bombay, North-West Provinces, Bengal, Punjab, Central Provinces; described by the 1891 report as normal mortality over a long series of years incl. famine periods. The 1881 report also prints Persons = 24.63 (PDF p.37, para 237).');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'life_expectancy', 'census_actuarial_le_female', '1881', 1881, 25.58, 'census-actuarial-reports-1881-1951', '1931 Actuarial Report (in reprint volume), Table XXXI ''Comparative Expectations of Life at decennial ages, as deduced from the results of the 1881, 1891, 1901, 1911 and 1931 Censuses'', All India, age 0 (FEMALE LIVES)', 'PDF p.384 (males) & p.386 (females); printed pp.358, 360', '2026-10-16', null, false, 'FEMALES only (table prints no persons figure). Life table derived at this census for British Indian provinces. Hardy 1881 tables: ''India (combined provinces)'' = Madras, Bombay, North-West Provinces, Bengal, Punjab, Central Provinces; described by the 1891 report as normal mortality over a long series of years incl. famine periods. The 1881 report also prints Persons = 24.63 (PDF p.37, para 237).');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'life_expectancy', 'census_actuarial_le_male', '1891', 1891, 24.59, 'census-actuarial-reports-1881-1951', '1931 Actuarial Report (in reprint volume), Table XXXI ''Comparative Expectations of Life at decennial ages, as deduced from the results of the 1881, 1891, 1901, 1911 and 1931 Censuses'', All India, age 0 (MALE LIVES)', 'PDF p.384 & p.386; printed pp.358, 360', '2026-10-16', null, true, 'MALES only (table prints no persons figure). Life table derived at this census for British Indian provinces. Mortality of the decade 1881-91 only; combined area of provinces investigated (1891 report compares Madras, Bengal, Bombay, NWP, Punjab).');
