insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1881', 1881, 4.8, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, false, 'Printed as 48 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. 1881-1891 classification Learning/Literate/Illiterate; 1901 report says those ''learning'' were counted, and the 1911 report judged 1881 overstated.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1891', 1891, 5.6, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, false, 'Printed as 56 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. Same classification as 1881; 1901 report notes about 32 million people in Central India, Kashmir, Rajputana etc. were left out of the 1891 literacy figures.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1901', 1901, 5.3, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, true, 'Printed as 53 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. From 1901 only literate/illiterate (learning category dropped) - break. 1901 report: ''53 persons per mille are literate'' of the total population.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1911', 1911, 5.9, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, false, 'Printed as 59 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. 1911: literate = able to write a letter to a friend and read the reply; 1931 report says figures from 1901 onward are comparable.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1921', 1921, 7.2, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, false, 'Printed as 72 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. Consistent with 1931 report: 1921 literates were 7.1 per cent of total population.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1931', 1931, 9.5, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, true, 'Printed as 95 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. CAUTION: 95 (M 156, F 29) equals the 1931 India Report''s ''literates per mille aged 5 and over'', not per total population (the same report puts literates at about 8.0 per cent of total population) - basis differs from 1921.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1941', 1941, 16.1, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, true, 'Printed as 161 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. 1941 figures were provisional totals struck by enumerators and never sorted; source warns they may include partial (read-only) literacy and be in excess.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1951', 1951, 16.7, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, true, 'Printed as 167 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. After partition (Indian Union) - territory break.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1961', 1961, 24.0, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, false, 'Printed as 240 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. After partition.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy_per1000_orgi1971', '1971', 1971, 29.3, 'census-1971-monograph9-literacy', 'Statement of the number of literates per 1,000 of population and of each sex from the 1881 Census (persons column)', 'PDF p.6 (printed p.ii)', '2026-10-16', null, false, 'Printed as 293 literate persons per 1,000 persons; value = printed figure / 10 (per cent of population, all ages). Source labels 1881-1941 ''Before partition'' and 1951-1971 ''After partition''. After partition.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy', '1951', 1951, 18.32, 'mospi-women-men-2016-ch3', 'Table 3.1: Trend in Literacy Rates in Post Independent India (Combined, Total)', 'PDF p.5 (printed p.41)', '2026-10-16', null, false, 'Effective literacy rate (literates / population of the age base). Census of India (ORGI) figures as reproduced by MoSPI. Population aged 5+; source footnote: 1951 persons figure is an effective literacy rate. Often quoted elsewhere as 18.33.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy', '1961', 1961, 28.31, 'mospi-women-men-2016-ch3', 'Table 3.1: Trend in Literacy Rates in Post Independent India (Combined, Total)', 'PDF p.5 (printed p.41)', '2026-10-16', null, false, 'Effective literacy rate (literates / population of the age base). Census of India (ORGI) figures as reproduced by MoSPI. Population aged 5+. Often quoted elsewhere as 28.30.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy', '1971', 1971, 34.45, 'mospi-women-men-2016-ch3', 'Table 3.1: Trend in Literacy Rates in Post Independent India (Combined, Total)', 'PDF p.5 (printed p.41)', '2026-10-16', null, false, 'Effective literacy rate (literates / population of the age base). Census of India (ORGI) figures as reproduced by MoSPI. Population aged 5+.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy', '1981', 1981, 43.57, 'mospi-women-men-2016-ch3', 'Table 3.1: Trend in Literacy Rates in Post Independent India (Combined, Total)', 'PDF p.5 (printed p.41)', '2026-10-16', null, true, 'Effective literacy rate (literates / population of the age base). Census of India (ORGI) figures as reproduced by MoSPI. Population aged 7+ (age base changed from 5+) and excludes Assam (no 1981 census) - break. Also matches ORGI ''Literacy Trends in the 1980s in India'' (Census 1991) appendix table.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy', '1991', 1991, 52.21, 'mospi-women-men-2016-ch3', 'Table 3.1: Trend in Literacy Rates in Post Independent India (Combined, Total)', 'PDF p.5 (printed p.41)', '2026-10-16', null, true, 'Effective literacy rate (literates / population of the age base). Census of India (ORGI) figures as reproduced by MoSPI. Population aged 7+; excludes Jammu & Kashmir (no 1991 census); Assam included again - coverage break. Also matches ORGI ''Literacy Trends in the 1980s in India''.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy', '2001', 2001, 64.83, 'mospi-women-men-2016-ch3', 'Table 3.1: Trend in Literacy Rates in Post Independent India (Combined, Total)', 'PDF p.5 (printed p.41)', '2026-10-16', null, true, 'Effective literacy rate (literates / population of the age base). Census of India (ORGI) figures as reproduced by MoSPI. Population aged 7+; J&K included; excludes Mao Maram, Paomata and Purul sub-divisions of Senapati district, Manipur - coverage break.');
insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'literacy', 'census_literacy', '2011', 2011, 72.98, 'mospi-women-men-2016-ch3', 'Table 3.1: Trend in Literacy Rates in Post Independent India (Combined, Total)', 'PDF p.5 (printed p.41)', '2026-10-16', null, false, 'Effective literacy rate (literates / population of the age base). Census of India (ORGI) figures as reproduced by MoSPI. Population aged 7+; final Census 2011 figure (the provisional figure was 74.04).');
